SELECT  FROM TBL_DEVICE_INFO

    LINE_ID = #{lineId,jdbcType=VARCHAR}
    AND STATION_ID = #{stationId,jdbcType=VARCHAR}
    AND DEVICE_TYPE = #{deviceType,jdbcType=VARCHAR}
    AND MANAGE_MODE = #{manageMode,jdbcType=VARCHAR}

        AND (DEVICE_ID LIKE '%' || #{keyword,jdbcType=VARCHAR} || '%' OR DEVICE_NAME LIKE '%' || #{keyword,jdbcType=VARCHAR} || '%')

    AND ACC_IS_DELETED = '0'

ORDER BY LINE_ID, STATION_ID, DEVICE_ID

